ob_start(); session_start();
if(!isset($_SESSION['logged_in'])||$_SESSION['logged_in']!==true){$api=isset($_GET['action'])||($_SERVER['REQUEST_METHOD']??'')==='POST';if($api){while(ob_get_level())ob_end_clean();header('Content-Type: application/json');http_response_code(401);echo json_encode(['success'=>false,'message'=>'Your session has expired. Please log in again.']);exit;}header('Location: login.php');exit;}
/* Self-contained database layer to avoid deployment filename/dependency failures. */
function license_db(): PDO {
    static $db=null; if($db instanceof PDO)return $db;
    $url=getenv('DATABASE_URL'); if(!$url)throw new RuntimeException('DATABASE_URL is not configured in Render.');
    if(!in_array('pgsql',PDO::getAvailableDrivers(),true))throw new RuntimeException('PDO PostgreSQL driver (pdo_pgsql) is not enabled.');
    $p=parse_url($url); if(!$p||empty($p['host'])||empty($p['user'])||empty($p['path']))throw new RuntimeException('DATABASE_URL is invalid.');
    $dsn=sprintf('pgsql:host=%s;port=%d;dbname=%s',$p['host'],(int)($p['port']??5432),ltrim($p['path'],'/'));
    $db=new PDO($dsn,urldecode($p['user']),urldecode($p['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); return $db;
}
function ensure_license_table(): void {
 $db=license_db();
 $db->exec("CREATE TABLE IF NOT EXISTS public.coffee_licenses (
 id BIGSERIAL PRIMARY KEY, license_sale_season VARCHAR(20) NOT NULL, license_category VARCHAR(255) NOT NULL,
 company_name VARCHAR(300) NOT NULL, postal_address TEXT, region VARCHAR(120), email_address VARCHAR(255),
 tin_no VARCHAR(80), tel_no VARCHAR(80), license_no VARCHAR(120), issued_date DATE, expire_date DATE,
 created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP)");
 $cols=['license_sale_season'=>'VARCHAR(20)','license_category'=>'VARCHAR(255)','company_name'=>'VARCHAR(300)','postal_address'=>'TEXT','region'=>'VARCHAR(120)','email_address'=>'VARCHAR(255)','tin_no'=>'VARCHAR(80)','tel_no'=>'VARCHAR(80)','license_no'=>'VARCHAR(120)','issued_date'=>'DATE','expire_date'=>'DATE','created_at'=>'TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP','updated_at'=>'TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP'];
 $q=$db->prepare("SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='coffee_licenses' AND column_name=:c");
 foreach($cols as $c=>$t){$q->execute(['c'=>$c]);if(!$q->fetchColumn())$db->exec('ALTER TABLE public.coffee_licenses ADD COLUMN "'.$c.'" '.$t);}
 $db->exec("CREATE INDEX IF NOT EXISTS idx_license_season ON public.coffee_licenses(license_sale_season)");
 $db->exec("CREATE INDEX IF NOT EXISTS idx_license_category ON public.coffee_licenses(license_category)");
 $db->exec("CREATE INDEX IF NOT EXISTS idx_license_region ON public.coffee_licenses(region)");
 $db->exec("CREATE INDEX IF NOT EXISTS idx_license_company ON public.coffee_licenses(company_name)");
}
function license_delete_all(): int {ensure_license_table();return license_db()->exec('DELETE FROM public.coffee_licenses');}
function lj(bool $ok,string $msg='',array $data=[],int $status=200):void{while(ob_get_level())ob_end_clean();http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode(['success'=>$ok,'message'=>$msg,'data'=>$data],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function lnrm($v):string{$s=strtolower(trim((string)$v));$s=preg_replace('/[^a-z0-9]+/','_',$s);return trim($s,'_');}
function ldate($v):?string{if($v===null)return null;$s=trim((string)$v);if($s===''||$s==='-')return null;if(is_numeric($s)&&((float)$s)>20000){$d=new DateTime('1899-12-30');$d->modify('+'.(int)floor((float)$s).' days');return $d->format('Y-m-d');}$ts=strtotime($s);return $ts===false?null:date('Y-m-d',$ts);}
function colidx(string $l):int{$n=0;foreach(str_split($l)as$c)$n=$n*26+(ord(strtoupper($c))-64);return$n-1;}
function parse_xlsx(string$f):array{if(!class_exists('ZipArchive'))throw new RuntimeException('ZipArchive is required to read Excel files.');$z=new ZipArchive();if($z->open($f)!==true)throw new RuntimeException('The Excel workbook could not be opened.');$ss=[];$x=$z->getFromName('xl/sharedStrings.xml');if($x!==false){$xml=simplexml_load_string($x);foreach($xml->si??[] as$si){$p=[];if(isset($si->t))$p[]=(string)$si->t;if(isset($si->r))foreach($si->r as$r)$p[]=(string)$r->t;$ss[]=implode('',$p);}}$sheet=$z->getFromName('xl/worksheets/sheet1.xml');if($sheet===false)throw new RuntimeException('Worksheet sheet1.xml was not found.');$xml=simplexml_load_string($sheet);$rows=[];foreach($xml->sheetData->row as$row){$o=[];foreach($row->c as$c){preg_match('/([A-Z]+)\d+/',(string)$c['r'],$m);$i=colidx($m[1]??'A');$t=(string)$c['t'];$v=$t==='s'?($ss[(int)$c->v]??''):($t==='inlineStr'?(string)$c->is->t:(string)$c->v);$o[$i]=$v;}if($o){ksort($o);$full=array_fill(0,max(array_keys($o))+1,'');foreach($o as$i=>$v)$full[$i]=$v;$rows[]=$full;}}$z->close();return$rows;}
function parse_file(string$f,string$ext):array{if(in_array($ext,['xlsx','xlsm','xltx'],true))return parse_xlsx($f);if($ext==='csv'){$a=[];$h=fopen($f,'rb');while(($r=fgetcsv($h))!==false)$a[]=$r;fclose($h);return$a;}throw new RuntimeException('Please upload .xlsx, .xlsm, .xltx or .csv.');}
function aliases():array{return['license_sale_season'=>['license_sale_season','sale_season','season'],'license_category'=>['license_category','category'],'company_name'=>['company_individual_name','company_name','company_individual'],'postal_address'=>['postal_address','address'],'region'=>['region'],'email_address'=>['email_address','email'],'tin_no'=>['tin_no','tin'],'tel_no'=>['tel_no','telephone_no','phone_no','telephone'],'license_no'=>['license_no','licence_no','license_number','licence_number'],'issued_date'=>['issued_date','issue_date'],'expire_date'=>['expire_date','expiry_date','expiration_date']];}
function maphead(array$h):array{$n=array_map('lnrm',$h);$m=[];foreach(aliases()as$f=>$aa){$m[$f]=null;foreach($aa as$a){$i=array_search($a,$n,true);if($i!==false){$m[$f]=$i;break;}}}return$m;}
function upload():void{if(!isset($_FILES['license_excel']))lj(false,'Please select the licence Excel file.',[],400);$f=$_FILES['license_excel'];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)lj(false,'The selected file could not be uploaded.',[],400);try{$rows=parse_file($f['tmp_name'],strtolower(pathinfo($f['name'],PATHINFO_EXTENSION)));}catch(Throwable$e){lj(false,$e->getMessage(),[],400);}if(count($rows)<2)lj(false,'The workbook contains no licence data.',[],400);$hi=null;for($i=0;$i<min(15,count($rows));$i++){$m=maphead($rows[$i]);if($m['license_sale_season']!==null&&$m['license_category']!==null&&$m['company_name']!==null){$hi=$i;break;}}if($hi===null)lj(false,'Could not identify the licence header row. Expected the 11-column licence template.',[],400);$m=maphead($rows[$hi]);$missing=[];foreach($m as$k=>$v)if($v===null)$missing[]=$k;if($missing)lj(false,'Upload stopped. Missing column(s): '.implode(', ',$missing).'.',[],400);
 $records=[];$errors=[];for($ri=$hi+1;$ri<count($rows);$ri++){$r=$rows[$ri];$g=fn($k)=>trim((string)($r[$m[$k]]??''));$season=$g('license_sale_season');$cat=$g('license_category');$company=$g('company_name');if($season===''&&$cat===''&&$company==='')continue;if($season===''||$cat===''||$company===''){$errors[]=$ri+1;continue;}$records[]=['license_sale_season'=>$season,'license_category'=>$cat,'company_name'=>$company,'postal_address'=>$g('postal_address'),'region'=>$g('region'),'email_address'=>$g('email_address'),'tin_no'=>$g('tin_no'),'tel_no'=>$g('tel_no'),'license_no'=>($g('license_no')==='-'?'':$g('license_no')),'issued_date'=>ldate($g('issued_date')),'expire_date'=>ldate($g('expire_date'))];}
 if($errors)lj(false,'Some rows are missing mandatory Season, Category or Company/Individual Name. Nothing was uploaded.',['excel_rows'=>$errors],400);if(!$records)lj(false,'No valid licence records were found.',[],400);ensure_license_table();$db=license_db();$replace=($_POST['replace_seasons']??'')==='1';$seasons=array_values(array_unique(array_column($records,'license_sale_season')));if(!$replace){$ph=implode(',',array_fill(0,count($seasons),'?'));$q=$db->prepare("SELECT license_sale_season,COUNT(*) n FROM public.coffee_licenses WHERE license_sale_season IN ($ph) GROUP BY license_sale_season");$q->execute($seasons);$existing=$q->fetchAll();if($existing)lj(true,'Existing records were found for one or more uploaded seasons. Confirm replacement to avoid duplicates.',['requires_confirmation'=>true,'existing'=>$existing,'incoming'=>count($records)]);}
 $db->beginTransaction();try{if($replace){$ph=implode(',',array_fill(0,count($seasons),'?'));$d=$db->prepare("DELETE FROM public.coffee_licenses WHERE license_sale_season IN ($ph)");$d->execute($seasons);}$ins=$db->prepare("INSERT INTO public.coffee_licenses(license_sale_season,license_category,company_name,postal_address,region,email_address,tin_no,tel_no,license_no,issued_date,expire_date) VALUES(:license_sale_season,:license_category,:company_name,:postal_address,:region,:email_address,:tin_no,:tel_no,:license_no,:issued_date,:expire_date)");foreach($records as$r)$ins->execute($r);$db->commit();}catch(Throwable$e){if($db->inTransaction())$db->rollBack();error_log('Licence upload: '.$e->getMessage());lj(false,'Licence records could not be saved.',[],500);}lj(true,'Licence data uploaded successfully.',['processed'=>count($records),'seasons'=>$seasons]);}
function filters():void{ensure_license_table();$db=license_db();lj(true,'',['seasons'=>$db->query("SELECT DISTINCT license_sale_season FROM public.coffee_licenses WHERE BTRIM(COALESCE(license_sale_season,''))<>'' ORDER BY license_sale_season DESC")->fetchAll(PDO::FETCH_COLUMN),'categories'=>$db->query("SELECT DISTINCT license_category FROM public.coffee_licenses WHERE BTRIM(COALESCE(license_category,''))<>'' ORDER BY license_category")->fetchAll(PDO::FETCH_COLUMN),'regions'=>$db->query("SELECT DISTINCT region FROM public.coffee_licenses WHERE BTRIM(COALESCE(region,''))<>'' ORDER BY region")->fetchAll(PDO::FETCH_COLUMN)]);}
function fetchrows():void{ensure_license_table();$db=license_db();$w=[];$p=[];foreach(['season'=>'license_sale_season','category'=>'license_category','region'=>'region']as$q=>$c){$v=trim($_GET[$q]??'');if($v!==''){$w[]="$c=:$q";$p[$q]=$v;}}$search=trim($_GET['search']??'');if($search!==''){$w[]="(company_name ILIKE :s OR COALESCE(license_no,'') ILIKE :s OR COALESCE(tin_no,'') ILIKE :s OR COALESCE(tel_no,'') ILIKE :s OR COALESCE(email_address,'') ILIKE :s)";$p['s']='%'.$search.'%';}$sql="SELECT id,license_sale_season,license_category,company_name,postal_address,region,email_address,tin_no,tel_no,license_no,TO_CHAR(issued_date,'DD/MM/YYYY') issued_date,TO_CHAR(expire_date,'DD/MM/YYYY') expire_date FROM public.coffee_licenses".($w?' WHERE '.implode(' AND ',$w):'')." ORDER BY license_sale_season DESC,license_category,company_name";$q=$db->prepare($sql);$q->execute($p);$rows=$q->fetchAll();lj(true,'',['rows'=>$rows,'count'=>count($rows)]);}
function stats():void{ensure_license_table();$db=license_db();$season=trim($_GET['season']??'');$w=$season!==''?' WHERE license_sale_season=:s':'';$p=$season!==''?['s'=>$season]:[];$q=$db->prepare("SELECT COUNT(*) total,COUNT(DISTINCT company_name) entities,COUNT(DISTINCT license_category) categories,COUNT(DISTINCT NULLIF(BTRIM(region),'')) regions FROM public.coffee_licenses$w");$q->execute($p);$summary=$q->fetch();$q=$db->prepare("SELECT license_category label,COUNT(*) value FROM public.coffee_licenses$w GROUP BY license_category ORDER BY value DESC,label");$q->execute($p);$cats=$q->fetchAll();$q=$db->prepare("SELECT COALESCE(NULLIF(BTRIM(region),''),'Unspecified') label,COUNT(*) value FROM public.coffee_licenses$w GROUP BY 1 ORDER BY value DESC,label");$q->execute($p);lj(true,'',['summary'=>$summary,'categories'=>$cats,'regions'=>$q->fetchAll()]);}
function update():void{ensure_license_table();$db=license_db();$in=json_decode(file_get_contents('php://input'),true)?:[];$id=(int)($in['id']??0);if($id<=0)lj(false,'Invalid licence row.',[],400);$fields=['license_sale_season','license_category','company_name','postal_address','region','email_address','tin_no','tel_no','license_no','issued_date','expire_date'];$set=[];$p=['id'=>$id];foreach($fields as$f)if(array_key_exists($f,$in)){$v=$in[$f];if(in_array($f,['issued_date','expire_date'],true))$v=ldate($v);$set[]="$f=:$f";$p[$f]=$v;}if(!$set)lj(false,'No changes supplied.',[],400);$q=$db->prepare('UPDATE public.coffee_licenses SET '.implode(',',$set).',updated_at=CURRENT_TIMESTAMP WHERE id=:id');$q->execute($p);lj(true,'Licence record updated successfully.');}
function del():void{ensure_license_table();$in=json_decode(file_get_contents('php://input'),true)?:[];$id=(int)($in['id']??0);if($id<=0)lj(false,'Invalid licence row.',[],400);$q=license_db()->prepare('DELETE FROM public.coffee_licenses WHERE id=:id');$q->execute(['id'=>$id]);lj(true,'Licence record deleted successfully.');}
try{if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&isset($_FILES['license_excel']))upload();$a=$_GET['action']??'';if($a==='filters')filters();if($a==='fetch')fetchrows();if($a==='stats')stats();if($a==='update'&&($_SERVER['REQUEST_METHOD']??'')==='POST')update();if($a==='delete'&&($_SERVER['REQUEST_METHOD']??'')==='POST')del();if($a==='delete_all'&&($_SERVER['REQUEST_METHOD']??'')==='POST')lj(true,'All licence data deleted.',['deleted'=>license_delete_all()]);ensure_license_table();}catch(Throwable $e){
    error_log('Licences: '.$e->getMessage());
    if(isset($_GET['action'])||($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
        lj(false,'Licence operation failed. '.$e->getMessage(),[],500);
    }
    /* Never leave the normal module page blank if PostgreSQL initialization fails. */
    $license_page_error=$e->getMessage();
}
