<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coffee Licences</title><style>
*{box-sizing:border-box}html,body{margin:0;height:100%;font-family:Arial,sans-serif;background:#f7f4f2;color:#382b26}body{overflow:hidden}.app{height:100vh;padding:8px;display:grid;grid-template-rows:auto auto auto minmax(0,1fr);gap:6px}.toolbar,.filters{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.toolbar{justify-content:space-between}.title{font-size:15px;font-weight:800;color:#4b342c}.muted{font-size:9px;color:#8b7d77}.controls{display:flex;gap:5px;align-items:center;flex-wrap:wrap}select,button,input{height:30px;border:1px solid #d9cfca;border-radius:6px;background:#fff;padding:0 9px;font-size:11px;color:#4b342c}button{cursor:pointer;font-weight:700}.primary{background:#5d4037;color:#fff;border-color:#5d4037}.danger{color:#9a2f28}.settings{position:relative}.menu{display:none;position:absolute;right:0;top:34px;background:#fff;border:1px solid #ddd2cd;border-radius:7px;padding:6px;min-width:180px;z-index:30;box-shadow:0 8px 22px #0002}.menu.open{display:block}.menu button{width:100%;text-align:left;border:0}.uploadbox{display:none;gap:5px;align-items:center}.uploadbox.open{display:flex}.msg{font-size:10px;padding:5px 8px;border-radius:5px;display:none}.msg.ok{display:block;background:#eaf5ec;color:#276536}.msg.err{display:block;background:#faecea;color:#8a3029}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.kpi{background:#fff;border:1px solid #e6ddd9;border-radius:7px;padding:7px 9px}.kpi span{font-size:8px;color:#8b7d77;text-transform:uppercase}.kpi strong{display:block;font-size:16px;color:#4b342c;margin-top:2px}.card{min-height:0;background:#fff;border:1px solid #e6ddd9;border-radius:8px;overflow:hidden;display:flex;flex-direction:column}.tablewrap{min-height:0;overflow:auto;flex:1}table{border-collapse:collapse;width:100%;min-width:1500px;font-size:9px}th,td{padding:5px 6px;border-bottom:1px solid #eee7e4;white-space:nowrap;text-align:left}thead th{position:sticky;top:0;background:#4b342c;color:#fff;z-index:3;font-size:8px}.actions{display:none}.editmode .actions{display:table-cell}.rowbtn{height:23px;padding:0 5px;font-size:9px}.count{font-size:9px;color:#776861;margin-left:auto}.search{min-width:180px}.export{background:#fff}@media(max-width:900px){body{overflow:auto}.app{height:auto;min-height:100vh}.kpis{grid-template-columns:repeat(2,1fr)}.card{min-height:70vh}.filters>*{flex:1 1 150px}}@media(max-width:600px){.app{padding:5px}.kpis{grid-template-columns:1fr 1fr}.uploadbox.open{width:100%;flex-wrap:wrap}.title{font-size:13px}}
</style></head><body><div class="app"><?php if(!empty($license_page_error)): ?><div class="msg err" style="display:block"><strong>Licence module database error:</strong> <?= htmlspecialchars($license_page_error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><div class="toolbar"><div><span class="title">Coffee Licences</span> <span class="muted">Licence register stored in PostgreSQL</span></div><div class="controls"><button class="export" onclick="exportCsv()">⇩ Export CSV</button><div class="settings"><button onclick="toggleSettings(event)">⚙ Settings</button><div class="menu" id="settings"><button onclick="showUpload()">↑ Upload Licence Excel</button><button onclick="toggleEdit()">✎ Edit records</button><button class="danger" onclick="deleteAll()">⌫ Delete all data</button></div></div></div></div>
<div><div class="filters"><select id="season"><option value="">All Sale Seasons</option></select><select id="category"><option value="">All Licence Categories</option></select><select id="region"><option value="">All Regions</option></select><input id="search" class="search" placeholder="Search company, licence, TIN, tel..."><button onclick="refresh()">↻ Refresh</button><div class="uploadbox" id="uploadbox"><input type="file" id="file" accept=".xlsx,.xlsm,.xltx,.csv"><button class="primary" onclick="upload(false)">Upload Licences</button></div><span class="count" id="count"></span></div><div class="msg" id="msg"></div></div>
<div class="kpis"><div class="kpi"><span>Licence Records</span><strong id="kTotal">0</strong></div><div class="kpi"><span>Companies / Individuals</span><strong id="kEntities">0</strong></div><div class="kpi"><span>Licence Categories</span><strong id="kCategories">0</strong></div><div class="kpi"><span>Regions</span><strong id="kRegions">0</strong></div></div>
<div class="card" id="card"><div class="tablewrap"><table id="table"></table></div></div></div><script>
const $=id=>document.getElementById(id);const cols=[['license_sale_season','Sale Season'],['license_category','Licence Category'],['company_name','Company / Individual Name'],['postal_address','Postal Address'],['region','Region'],['email_address','Email Address'],['tin_no','TIN No.'],['tel_no','Tel. No.'],['license_no','Licence No.'],['issued_date','Issued Date'],['expire_date','Expire Date']];let rows=[],edit=false;
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function msg(t,ok=true){let m=$('msg');m.className='msg '+(ok?'ok':'err');m.textContent=t;setTimeout(()=>m.className='msg',6500)}async function api(u,o){let r=await fetch(u,o),j=await r.json();if(!r.ok||j.success===false)throw new Error(j.message||'Request failed');return j.data}
function toggleSettings(e){e?.stopPropagation();$('settings').classList.toggle('open')}document.addEventListener('click',e=>{if(!e.target.closest('.settings'))$('settings').classList.remove('open')});function showUpload(){$('settings').classList.remove('open');$('uploadbox').classList.toggle('open')}function toggleEdit(){edit=!edit;$('card').classList.toggle('editmode',edit);$('settings').classList.remove('open');render()}
async function loadFilters(){let d=await api('licenses.php?action=filters');const fill=(id,a,label)=>{$(id).innerHTML=`<option value="">${label}</option>`+a.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')};fill('season',d.seasons,'All Sale Seasons');fill('category',d.categories,'All Licence Categories');fill('region',d.regions,'All Regions')}
function qs(){let p=new URLSearchParams();['season','category','region','search'].forEach(k=>{let v=$(k).value.trim();if(v)p.set(k,v)});return p.toString()}
async function loadRows(){let d=await api('licenses.php?action=fetch&'+qs());rows=d.rows;$('count').textContent=d.count.toLocaleString()+' record(s)';render()}async function loadStats(){let p=new URLSearchParams();if($('season').value)p.set('season',$('season').value);let d=await api('licenses.php?action=stats&'+p);$('kTotal').textContent=Number(d.summary.total||0).toLocaleString();$('kEntities').textContent=Number(d.summary.entities||0).toLocaleString();$('kCategories').textContent=Number(d.summary.categories||0).toLocaleString();$('kRegions').textContent=Number(d.summary.regions||0).toLocaleString()}
function render(){let h='<thead><tr>'+cols.map(c=>`<th>${c[1]}</th>`).join('')+'<th class="actions">Actions</th></tr></thead><tbody>';for(const r of rows){h+='<tr>'+cols.map(c=>`<td>${esc(r[c[0]]||'')}</td>`).join('')+`<td class="actions"><button class="rowbtn" onclick="editRow(${r.id})">Edit</button> <button class="rowbtn danger" onclick="deleteRow(${r.id})">Delete</button></td></tr>`}h+='</tbody>';$('table').innerHTML=h}
async function refresh(){try{await Promise.all([loadRows(),loadStats()])}catch(e){msg(e.message,false)}}['season','category','region'].forEach(id=>$(id).addEventListener('change',refresh));let st;$('search').addEventListener('input',()=>{clearTimeout(st);st=setTimeout(loadRows,300)})
async function upload(confirmReplace){let f=$('file').files[0];if(!f){msg('Select the licence Excel file first.',false);return}let fd=new FormData();fd.append('license_excel',f);if(confirmReplace)fd.append('replace_seasons','1');try{let r=await fetch('licenses.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||j.success===false)throw new Error(j.message||'Upload failed');if(j.data?.requires_confirmation){let detail=(j.data.existing||[]).map(x=>`${x.license_sale_season}: ${x.n} existing`).join('\n');if(confirm('Existing licence data was found:\n'+detail+'\n\nReplace the existing data for these season(s) with this workbook?'))return upload(true);return}msg(j.message);await loadFilters();await refresh()}catch(e){msg(e.message,false)}}
async function editRow(id){let r=rows.find(x=>Number(x.id)===Number(id));if(!r)return;let out={id};for(const [k,label] of cols){let v=prompt(label,r[k]??'');if(v===null)return;out[k]=v}try{await api('licenses.php?action=update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(out)});msg('Licence record updated.');await loadFilters();await refresh()}catch(e){msg(e.message,false)}}async function deleteRow(id){if(!confirm('Delete this licence record?'))return;try{await api('licenses.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});msg('Licence record deleted.');await refresh()}catch(e){msg(e.message,false)}}async function deleteAll(){if(!confirm('Delete ALL licence records from the database? This cannot be undone.'))return;try{await api('licenses.php?action=delete_all',{method:'POST'});msg('All licence records deleted.');await loadFilters();await refresh()}catch(e){msg(e.message,false)}}
function exportCsv(){if(!rows.length){msg('There is no displayed licence data to export.',false);return}let q=s=>`"${String(s??'').replace(/"/g,'""')}"`;let csv=[cols.map(c=>q(c[1])).join(',')].concat(rows.map(r=>cols.map(c=>q(r[c[0]])).join(','))).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.download='Coffee_Licences_'+($('season').value||'All_Seasons').replace('/','-')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
(async()=>{try{await loadFilters();await refresh()}catch(e){msg(e.message,false)}})();</script></body></html>
